SELECT activity__active_date__day as day, vm.value as habits_completed, ao.value as app_opens
FROM (
  SELECT activity__active_date__day, value FROM (
    SELECT * FROM (VALUES
      ('2026-07-11',497),('2026-07-09',478),('2026-07-06',501),('2026-07-08',507),('2026-07-10',512),('2026-07-07',601),('2026-07-12',546)
    ) AS t(day, value)
  )
) vm
JOIN (
  SELECT activity__active_date__day, value FROM (
    SELECT * FROM (VALUES
      ('2026-07-11',804),('2026-07-09',826),('2026-07-06',815),('2026-07-12',863),('2026-07-08',854),('2026-07-07',1032),('2026-07-10',876)
    ) AS t(day, value)
  )
) ao
ON vm.activity__active_date__day = ao.activity__active_date__day
;

SELECT SUM(habits_completed) as total_habits, SUM(app_opens) as total_sessions, CAST(SUM(habits_completed) AS DOUBLE)/SUM(app_opens) as avg_habits_per_session
FROM (
  SELECT day, CAST(value AS INTEGER) AS habits_completed FROM (VALUES
    ('2026-07-11',497),('2026-07-09',478),('2026-07-06',501),('2026-07-08',507),('2026-07-10',512),('2026-07-07',601),('2026-07-12',546)
  ) AS t(day, value)
) vm
JOIN (
  SELECT day, CAST(value AS INTEGER) AS app_opens FROM (VALUES
    ('2026-07-11',804),('2026-07-09',826),('2026-07-06',815),('2026-07-12',863),('2026-07-08',854),('2026-07-07',1032),('2026-07-10',876)
  ) AS t(day, value)
) ao
ON vm.day = ao.day
;
